import numpy as np

def classify(A, tol=1e-9):
    """Name the equilibrium of x' = A x from the trace and determinant."""
    A = np.asarray(A, dtype=float)
    tau, det = float(np.trace(A)), float(np.linalg.det(A))
    if abs(det) <= tol:
        return "degenerate"
    if det < 0:
        return "saddle"
    if abs(tau) <= tol:
        return "centre"
    side = "stable" if tau < 0 else "unstable"
    if tau * tau - 4 * det >= -tol:
        return side + " node"
    return side + " spiral"
